import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { checkColors, findColorLiterals } from "../scripts/check-colors";

describe("canonical application colors", () => {
  it("rejects unapproved literals throughout UI sources and SVG assets", () => {
    expect(checkColors()).toEqual([]);
  });
  it.each([
    "color: #abcdef;",
    "background: rgb(1 2 3 / 50%);",
    "hover:bg-blue-500",
    "dark:text-white",
    'fill="#abcd"',
    "var(--ink, #123)",
    "shadow-[0_0_8px_rgba(0,0,0,.4)]",
    "color: oklch(40% .1 260)",
    'stroke="white"',
    "bg-[navy]",
    "background: linear-gradient(white, rebeccapurple)",
  ])("detects %s", (source) => {
    expect(findColorLiterals(source).length).toBeGreaterThan(0);
  });
  it("preserves semantic CSS values", () => {
    expect(
      findColorLiterals(
        "color: currentColor; background: transparent; color: CanvasText;",
      ),
    ).toEqual([]);
  });
  it("keeps all consolidated primitives nonempty and uniquely named", () => {
    const css = readFileSync("src/app/theme-tokens.css", "utf8");
    const definitions = [...css.matchAll(/(--[\w-]+):\s*([^;]+);/g)];
    expect(definitions.length).toBeGreaterThan(300);
    const primitives = definitions.filter((m) => m[1].startsWith("--color-"));
    expect(new Set(primitives.map((m) => m[1])).size).toBe(primitives.length);
    for (const definition of definitions)
      expect(definition[2].trim()).not.toBe("");
  });
});
